def unit_of_work(metadata=None, timeout=None):
    """Decorator that adds timeout and metadata handling to Neo4j transaction functions.

    Each decorated function must accept a ``session`` as its first argument
    (matching the Neo4j driver ``Session`` interface) and then forward any
    additional arguments to a transaction handler.  The wrapper invokes the
    transaction using ``session.write_transaction`` and forwards the optional
    ``timeout`` and ``metadata`` parameters to the driver.

    Parameters
    ----------
    metadata : dict or None
        Dictionary of metadata.  It will be attached to the transaction.
    timeout : float or None
        Transaction timeout in seconds.  A negative timeout raises
        ``ValueError``.  ``None`` denotes the database default.

    Returns
    -------
    callable
        A wrapper function that executes the original function in a Neo4j
        transaction with the supplied configuration.
    """
    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict or None")

    # Validate timeout
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number or None")
        if timeout < 0:
            raise ValueError("timeout cannot be negative")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(session, *args, **kwargs):
            # Ensure the session object provides the expected API
            if not hasattr(session, "write_transaction"):
                raise AttributeError(
                    "The session object must provide a `write_transaction` method"
                )

            # Build transaction options dictionary
            config_options = {}
            if timeout is not None:
                config_options["timeout"] = timeout
            if metadata is not None:
                config_options["metadata"] = metadata

            try:
                return session.write_transaction(fn, *args, **kwargs, **config_options)
            except Exception as exc:
                # Re-raise with a more informative message
                raise RuntimeError(
                    f"Transaction failed while executing {fn.__name__}: {exc}"
                ) from exc

        return wrapper

    return decorator

