def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # basic validation
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    rows = []

    # prepend header if provided
    if header is not None:
        rows.append(header + "\n")

    try:
        # points is expected to be iterable of objects with .coordinate and .value
        points = getattr(self, "points", None)
        if points is None and hasattr(self, "__iter__"):
            points = self
        if points is None:
            raise AttributeError("Object does not contain points to iterate")

        for point in points:
            # collect elements for this row
            row_elems = []

            # handle coordinate
            coord = getattr(point, "coordinate", None)
            if coord is None:
                coord = getattr(point, "x", None)  # try fallback
            if coord is None:
                raise AttributeError("Point does not have a coordinate")

            # if coordinate is a single scalar, make it a list
            if isinstance(coord, (int, float, str)) and not isinstance(coord, (list, tuple, set)):
                coord_iter = [coord]
            else:
                coord_iter = coord

            row_elems.extend(str(c) for c in coord_iter)

            # handle value
            value = getattr(point, "value", None)
            if value is not None:
                if isinstance(value, (int, float, str)) and not isinstance(value, (list, tuple, set)):
                    value_iter = [value]
                else:
                    value_iter = value
                row_elems.extend(str(v) for v in value_iter)

            rows.append(separator.join(row_elems) + "\n")

    except Exception as exc:
        raise RuntimeError(f"Failed to convert graph to CSV: {exc}") from exc

    return "".join(rows)

