    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate coordinate and weight
    if not isinstance(coord, (list, tuple)):
        raise TypeError("coord must be a sequence of coordinates")
    if len(coord) != len(self.edges):
        raise ValueError(f"coord length {len(coord)} does not match histogram dimensionality {len(self.edges)}")
    if not isinstance(weight, (int, float)):
        raise TypeError("weight must be numeric")

    # Determine bin indices for each dimension
    indices = []
    for axis, c in zip(self.edges, coord):
        try:
            # numpy is expected to be available in the surrounding context
            import numpy as np
            idx = np.searchsorted(axis, c, side='right') - 1
        except Exception:
            # Fallback to a simple linear search if numpy is not available
            try:
                idx = next(i for i, val in enumerate(axis) if val > c) - 1
            except StopIteration:
                idx = len(axis) - 1
        # If the coordinate lies outside the edges, ignore it
        if idx < 0 or idx >= len(axis) - 1:
            return
        indices.append(idx)

    # Increment the histogram bin
    self.data[tuple(indices)] += weight

