    version = version.strip()
    if not version:
        return None

    # Split into components separated by '.'
    parts = version.split('.')
    # Work on the last component
    last = parts[-1]
    # Determine if last part consists only of digits
    if not last.isdigit():
        return None

    try:
        orig_num = int(last)
        new_num = orig_num + 1
    except Exception:
        return None

    # Preserve leading zero width if possible
    width = len(last)
    if new_num < 10 ** width:
        new_last = str(new_num).zfill(width)
    else:
        new_last = str(new_num)

    parts[-1] = new_last
    return '.'.join(parts)

def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not isinstance(version, str):
            raise TypeError("Version must be a string")
        if version == "":
            raise ValueError("Empty version string")

        parts = version.split('.')
        # Convert parts to integers, keep original widths
        nums = []
        widths = []
        for p in parts:
            if p == '':
                raise ValueError(f"Empty version component in '{version}'")
            try:
                num = int(p)
            except ValueError as e:
                raise ValueError(f"Non-numeric component '{p}' in version '{version}'") from e
            nums.append(num)
            widths.append(len(p))

        # Increment the last component
        nums[-1] += 1

        # Rebuild string with appropriate width (preserve leading zeros only if they were present)
        new_parts = []
        for num, width in zip(nums, widths):
            s = str(num)
            if width > len(s):
                s = s.zfill(width)
            new_parts.append(s)

        return ".".join(new_parts)
    except Exception as exc:
        # Re-raise as ValueError with context for consistency
        raise ValueError(f"Failed to compute next version for '{version}': {exc}") from exc

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    # Validate input
    if not isinstance(version, str):
        raise TypeError(f"Expected str, got {type(version).__name__}")
    version = version.strip()
    if not version:
        raise ValueError("Version string cannot be empty")

    parts = version.split('.')
    if not parts:
        raise ValueError("Invalid version format")

    # Ensure each part is numeric
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Non-numeric version part: '{part}'")

    # Increment the last part
    last_index = len(parts) - 1
    try:
        last_num = int(parts[last_index])
    except Exception as exc:
        raise ValueError(f"Unable to parse the last part: '{parts[last_index]}'") from exc

    new_last_num = last_num + 1
    original_width = len(parts[last_index])
    new_last_str = str(new_last_num)
    if len(new_last_str) < original_width:
        new_last_str = new_last_str.rjust(original_width, '0')

    new_parts = parts[:-1] + [new_last_str]
    return '.'.join(new_parts)

