def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Initialise containers if they haven't been defined already
    if not hasattr(self, "errors"):
        self.errors = []
    if not hasattr(self, "different_digests"):
        self.different_digests = []

    # The root inventory is expected to be loaded elsewhere and should be a dict
    root_inventory = getattr(self, "root_inventory", {})
    if not isinstance(root_inventory, dict):
        self.errors.append("Root inventory is not a dictionary.")
        return

    for idx, version_dir in enumerate(version_dirs, start=1):
        # Construct full path to the inventory file within the version directory
        inventory_path = os.path.join(version_dir, "inventory.json")

        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                try:
                    version_inventory = json.load(f)
                except ValueError as e:
                    self.errors.append(f"Invalid JSON in inventory for {version_dir}: {e}")
                    continue
        except FileNotFoundError:
            self.errors.append(f"Missing inventory file in version directory {version_dir}.")
            continue
        except OSError as e:
            self.errors.append(f"Unable to read inventory in {version_dir}: {e}")
            continue

        if not isinstance(version_inventory, dict):
            self.errors.append(f"Inventory in {version_dir} is not a dictionary.")
            continue

        # Compare each entry in the version inventory against the root inventory
        for path, v_digest in version_inventory.items():
            r_digest = root_inventory.get(path)
            if r_digest is None:
                # The file is new in this version; no comparison required
                continue
            if v_digest != r_digest:
                self.different_digests.append(
                    {
                        "version": idx,
                        "dir": version_dir,
                        "path": path,
                        "root_digest": r_digest,
                        "version_digest": v_digest,
                    }
                )

        # Also flag any files present in the root inventory that are missing
        # from this version's inventory
        for path, r_digest in root_inventory.items():
            if path not in version_inventory:
                self.different_digests.append(
                    {
                        "version": idx,
                        "dir": version_dir,
                        "path": path,
                        "root_digest": r_digest,
                        "version_digest": None,
                    }
                )
        # Ensure that each version has inventory up to that point:
        # if any file missing from the root inventory (i.e., it's a new file)
        # we simply ignore, as a new file is allowed. No further checks are
        # required at this stage.

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import json, os

        # Helper to load an inventory file expecting JSON
        def _load_inventory(path):
            try:
                with open(path, 'r', encoding='utf-8') as fd:
                    return json.load(fd)
            except FileNotFoundError:
                raise ValueError(f"Inventory file not found: {path}")
            except json.JSONDecodeError as e:
                raise ValueError(f"Invalid JSON in inventory {path}: {e}")

        # Path to the root inventory (should be present for reference)
        root_inv_path = os.path.join(self.root, 'inventory.json')
        root_inv = {}
        if os.path.exists(root_inv_path):
            root_inv = _load_inventory(root_inv_path)

        cumulative = {}
        digest_diffs = {}

        for idx, ver_dir in enumerate(version_dirs, start=1):
            inv_path = os.path.join(self.root, ver_dir, 'inventory.json')
            inventory = _load_inventory(inv_path)

            # Ensure that all entries from previous versions exist in this inventory
            missing = [p for p in cumulative if p not in inventory]
            if missing:
                raise ValueError(
                    f"Version {ver_dir} inventory is missing entries from earlier versions: {missing}"
                )

            # Check for digest changes compared to cumulative
            for path, old_digest in cumulative.items():
                new_digest = inventory[path]
                if new_digest != old_digest:
                    digest_diffs.setdefault(path, []).append(
                        (old_digest, new_digest)
                    )

            # Compare with root inventory digests if it exists
            for path, dig in inventory.items():
                if path in root_inv and root_inv[path] != dig:
                    digest_diffs.setdefault(path, []).append(
                        (root_inv[path], dig)
                    )

            # Update cumulative for next iteration
            cumulative.update(inventory)

        # Store differences for later validation
        self.digest_diffs = digest_diffs

        return digest_diffs

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        os = __import__('os')
        re = __import__('re')
    except Exception as e:
        return f"Import error: {e}"
    if path is None:
        return "No path provided"
    if not isinstance(path, str):
        return "Invalid path type (expected string)"
    try:
        if not os.path.exists(path):
            return "Path does not exist"
        if os.path.isfile(path):
            return 'file'
        if os.path.isdir(path):
            try:
                items = os.listdir(path)
            except Exception as e:
                return f"Cannot list directory: {e}"
            namaste_files = [f for f in items if re.match(r'^0=.*', f)]
            if not namaste_files:
                return "No Namaste file found"
            # Heuristic to differentiate root vs object:
            # If the directory contains a 'manifest' or 'index' file we treat it as root.
            # Otherwise treat it as an object directory.
            lower_items = [i.lower() for i in items]
            if ('manifest' in lower_items) or ('index' in lower_items) or any(f.startswith('audit.log') for f in items):
                return 'root'
            else:
                return 'object'
    except Exception as e:
        return f"Error processing path: {e}"
    return "Unknown type"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Use os module, assuming it is available in the environment
    try:
        if not os.path.exists(path):
            return f"path does not exist: {path!r}"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            try:
                # First look for a Namaste file under the directory itself
                for entry in os.listdir(path):
                    full_path = os.path.join(path, entry)
                    try:
                        if os.path.isfile(full_path) and entry.startswith("0="):
                            # A Namaste file directly under the directory indicates a root
                            return "root"
                    except OSError:
                        # Skip entries that cannot be accessed; handled below
                        pass
                # If no file found, look for a subdirectory whose name starts with "0="
                for entry in os.listdir(path):
                    full_path = os.path.join(path, entry)
                    try:
                        if os.path.isdir(full_path) and entry.startswith("0="):
                            # A subdirectory starting with "0=" indicates an object
                            return "object"
                    except OSError:
                        continue
                # If neither condition was met
                return "neither root nor object (missing '0=' file or subdirectory)"
            except PermissionError as e:
                return f"permission error listing directory: {e}"
            except OSError as e:
                return f"error accessing directory: {e}"
        return f"unknown filesystem type for path: {path!r}"
    except Exception as e:
        return f"unexpected error: {e}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate the params argument
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # If no bug IDs were provided, just return the params unchanged
    if not bug_ids:
        return params

    # Build a list of integer bug IDs, validating each entry
    bug_id_list = []
    for b in bug_ids:
        try:
            # Accept ints directly
            if isinstance(b, int):
                bug_id_list.append(b)
            # Accept numeric strings that represent integers
            elif isinstance(b, str) and b.isdigit():
                bug_id_list.append(int(b))
            else:
                raise ValueError(f"Invalid bug id: {b!r}")
        except Exception as exc:
            # Catch any unexpected type issues
            raise ValueError(f"Invalid bug id: {b!r}") from exc

    # If we have valid bug IDs, add them to the parameters
    if bug_id_list:
        # Use a sorted, unique list for consistency
        unique_ids = sorted(set(bug_id_list))
        # Bugzilla expects a comma-separated string for the 'ids' key
        params["ids"] = ",".join(map(str, unique_ids))

    return params

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params

        This method updates the `params` dictionary to include the
        provided `bug_ids` under the `ids` key, merging with any
        existing ids.

        Parameters
        ----------
        params : dict
            Existing Bugzilla query parameters. If ``None`` a new dictionary
            is created.
        bug_ids : Iterable[str | int] | str | int
            A single bug id, a string of comma separated ids, or an
            iterable of ids. Non-iterables are treated as a single id. If
            ``None`` or empty, no changes are made.

        Returns
        -------
        dict
            The updated parameters dictionary.
        """
        # Ensure params is a dict
        if params is None:
            params = {}
        elif not isinstance(params, dict):
            raise TypeError(f"params must be a dict, got {type(params).__name__}")

        # Normalise bug_ids into a list of strings
        ids_to_add = []
        if bug_ids is not None:
            # If a single int/str, wrap it
            if isinstance(bug_ids, (str, int)):
                # Allow comma separated string of ids
                if isinstance(bug_ids, str) and ',' in bug_ids:
                    parts = bug_ids.split(',')
                    for part in parts:
                        part = part.strip()
                        if part:
                            ids_to_add.append(part)
                else:
                    ids_to_add.append(str(bug_ids))
            else:
                try:
                    for entry in bug_ids:
                        if isinstance(entry, str):
                            for part in entry.split(','):
                                part = part.strip()
                                if part:
                                    ids_to_add.append(part)
                        else:
                            ids_to_add.append(str(entry))
                except TypeError:
                    raise TypeError(f"bug_ids must be an iterable of id-like values, got {type(bug_ids).__name__}")

        if not ids_to_add:
            return params  # nothing to add

        # Get existing ids from params (if any)
        existing_ids = []
        if 'ids' in params:
            existing = params['ids']
            if isinstance(existing, str):
                existing_ids = [x.strip() for x in existing.split(',') if x.strip()]
            elif isinstance(existing, (list, tuple)):
                existing_ids = [str(x).strip() for x in existing if str(x).strip()]
            else:
                # fall back to string conversion
                existing_ids = [str(existing).strip()]

        # Merge, deduplicate, maintain order (stable)
        combined_ids = list(dict.fromkeys(existing_ids + ids_to_add))

        # Set the merged ids back into params as a comma-separated string
        params['ids'] = ",".join(combined_ids)

        return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        return params
    # If bug_ids is a string, use it directly (assumed to be comma‑separated)
    if isinstance(bug_ids, (str, bytes)):
        ids_str = bug_ids.decode() if isinstance(bug_ids, bytes) else bug_ids
    else:
        try:
            bug_ids_iter = list(bug_ids)
        except TypeError:
            # Treat non‑iterable (e.g., int) as a single id
            bug_ids_iter = [bug_ids]
        # Convert each id to string and join with commas
        ids_str = ",".join(str(bid) for bid in bug_ids_iter)
    # Set the 'ids' parameter (overwriting if it already exists)
    params["ids"] = ids_str
    return params

def deep_merge_nodes(nodes):
    '''
    Merge duplicate keys in a list of (ScalarNode, value) tuples, deep merging
    MappingNode values. For non-MappingNode conflicts, the later value wins.
    '''
    from ruamel.yaml.nodes import MappingNode

    def merge_lists(left, right):
        """Merge two MappingNode value lists (list of tuples)."""
        merged = []
        # dictionary to group by key value
        key_map = {}
        for k, v in left:
            key_map[k.value] = (k, v)
        for k, v in right:
            key_val = k.value
            if key_val in key_map:
                _, existing_v = key_map[key_val]
                # both are MappingNode? deep merge
                if isinstance(existing_v, MappingNode) and isinstance(v, MappingNode):
                    merged_value = merge_lists(existing_v.value, v.value)
                    new_node = MappingNode(tag=existing_v.tag, value=merged_value)
                    key_map[key_val] = (k, new_node)
                else:
                    # last wins
                    key_map[key_val] = (k, v)
            else:
                key_map[key_val] = (k, v)
        # preserve order of first appearance
        for _, (k, v) in key_map.items():
            merged.append((k, v))
        return merged

    result_map = {}
    order = []

    for key, value in nodes:
        if not hasattr(key, 'value'):
            # skip invalid key
            continue
        key_val = key.value
        if key_val in result_map:
            existing_key, existing_value = result_map[key_val]
            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                merged_value = merge_lists(existing_value.value, value.value)
                new_node = MappingNode(tag=existing_value.tag, value=merged_value)
                # keep the original key node
                result_map[key_val] = (existing_key, new_node)
            else:
                # last wins
                result_map[key_val] = (key, value)
        else:
            result_map[key_val] = (key, value)
            order.append(key_val)

    # Construct final list preserving order
    merged_nodes = []
    for key_val in order:
        key_node, value_node = result_map[key_val]
        merged_nodes.append((key_node, value_node))

    return merged_nodes

def deep_merge_nodes(nodes):
    '''
    Given a list of (ScalarNode, Node) tuples that represent
    a YAML mapping, merge any duplicate keys recursively.
    Duplicate scalar keys are compared using the key node's .value attribute.
    If two values corresponding to the same key are MappingNode instances, the
    function performs a deep merge of the mappings.  Otherwise, the value from
    the latter node wins.
    '''
    if not isinstance(nodes, list):
        return []

    merged_dict = {}
    order = []

    # Helper to deep merge two MappingNode instances
    def _merge_mapping(a, b):
        if not hasattr(a, 'tag') or not hasattr(b, 'tag'):
            # not mapping nodes; last wins
            return b

        # Preserve original order: start with a's order, then b's new entries
        result = []
        seen = {}

        # Build dict of a's children
        for kid, val in a.value:
            key = kid.value
            seen[key] = (kid, val)

        # Merge b's children
        for kid, val in b.value:
            key = kid.value
            if key in seen:
                old_kid, old_val = seen[key]
                if hasattr(old_val, 'tag') and hasattr(val, 'tag'):
                    merged_val = _merge_mapping(old_val, val)
                else:
                    merged_val = val
                seen[key] = (old_kid, merged_val)
            else:
                seen[key] = (kid, val)

        # Build ordered result list
        used = set()
        for kid, val in a.value:
            key = kid.value
            if key in seen:
                _, merged_val = seen[key]
                result.append((kid, merged_val))
                used.add(key)
        for kid, val in b.value:
            key = kid.value
            if key not in used:
                result.append((kid, val))
                used.add(key)

        return type(a)(a.tag, result)

    for key_node, value_node in nodes:
        if not hasattr(key_node, 'value'):
            continue
        key = key_node.value
        if key in merged_dict:
            _, existing_value = merged_dict[key]
            if hasattr(existing_value, 'tag') and hasattr(value_node, 'tag'):
                merged_value = _merge_mapping(existing_value, value_node)
            else:
                merged_value = value_node
            merged_dict[key] = (existing_value, merged_value)
        else:
            merged_dict[key] = (key_node, value_node)
            order.append(key)

    return [(merged_dict[k][0], merged_dict[k][1]) for k in order]

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (key_node, value_node) tuples.

    Parameters
    ----------
    nodes : list
        A list of tuples where the first element is a ScalarNode instance
        (representing a key) and the second element is a node instance
        (MappingNode, ScalarNode, etc.) representing the value.

    Returns
    -------
    list
        A list of tuples containing the merged node structure.
    """
    def _merge_values(v1, v2):
        """
        Merge two node values. If both are MappingNodes, merge their mappings
        recursively; otherwise, return the second value (the latter wins).
        """
        try:
            # Determine if nodes represent mappings by inspecting their tag.
            tag1 = getattr(v1, "tag", None)
            tag2 = getattr(v2, "tag", None)
        except Exception:
            return v2

        if isinstance(tag1, str) and isinstance(tag2, str) and \
           tag1.endswith("map") and tag2.endswith("map"):
            # Merge mapping nodes.
            try:
                items1 = getattr(v1, "value", []) or []
                items2 = getattr(v2, "value", []) or []
            except Exception:
                return v2

            merged = {}
            for key_node, val_node in items1:
                try:
                    key = key_node.value
                except Exception:
                    key = None
                merged[key] = (key_node, val_node)

            for key_node, val_node in items2:
                try:
                    key = key_node.value
                except Exception:
                    key = None
                if key in merged:
                    _, existing_val = merged[key]
                    merged[key] = (key_node, _merge_values(existing_val, val_node))
                else:
                    merged[key] = (key_node, val_node)

            merged_list = [(k_node, v_node) for k_node, v_node in merged.values()]
            # Reconstruct the mapping node with the same constructor and tag.
            try:
                return v1.__class__(tag=v1.tag, value=merged_list)
            except Exception:
                # Fallback: return v2 if construction fails.
                return v2
        else:
            return v2

    if not isinstance(nodes, list):
        raise ValueError("Input must be a list of (key_node, value_node) tuples.")

    result = []
    seen_keys = {}

    for entry in nodes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            continue  # Skip malformed entries
        key_node, val_node = entry
        try:
            key = key_node.value
        except Exception:
            continue  # Skip if key extraction fails

        if key in seen_keys:
            _, existing_val = seen_keys[key]
            merged_val = _merge_values(existing_val, val_node)
            seen_keys[key] = (key_node, merged_val)
