def vertex3tuple(vertices):
    """Return 3 points for each vertex of the polygon. This will include the vertex
    and the two points on both sides of the vertex:

    Example:
        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3-tuples
        #A    B    C    D  -> of vertices
    """
    try:
        verts = list(vertices)
    except TypeError as exc:
        raise ValueError("vertices must be an iterable") from exc

    n = len(verts)
    if n == 0:
        return []
    if n < 3:
        raise ValueError("At least 3 vertices are required to form a polygon")

    three_tuples = [
        (verts[(i - 1) % n], verts[i], verts[(i + 1) % n])
        for i in range(n)
    ]
    return three_tuples

