        subprocess.run(["mkdir", "-p", dest_dir], check=True)

        # Determine extraction command based on file extension
        if archive_path.endswith(".zip"):
            command = ["unzip", archive_path, "-d", dest_dir]
            if filename is not None:
                command = ["unzip", archive_path, filename, "-d", dest_dir]
        elif archive_path.endswith(".tar"):
            command = ["tar", "-xf", archive_path, "-C", dest_dir]
            if filename is not None:
                command = ["tar", "-xf", archive_path, filename, "-C", dest_dir]
        elif archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
            command = ["tar", "-xzf", archive_path, "-C", dest_dir]
            if filename is not None:
                command = ["tar", "-xzf", archive_path, filename, "-C", dest_dir]
        elif archive_path.endswith(".tar.bz2") or archive_path.endswith(".tbz"):
            command = ["tar", "-xjf", archive_path, "-C", dest_dir]
            if filename is not None:
                command = ["tar", "-xjf", archive_path, filename, "-C", dest_dir]
        else:
            raise ValueError(f"Unsupported archive format for {archive_path}")

        subprocess.run(command, check=True)

    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Extraction failed for {archive_path}") from exc

    return f"file://{dest_dir}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        tmp_dir = str(tmp_path).rstrip("/")
    except Exception:
        # If tmp_path is not a string-like (e.g., PosixPath), fall back to its str representation
        tmp_dir = str(tmp_path)

    # Determine the extraction directory name
    if filename:
        dir_name = filename
    else:
        # Remove known archive suffixes to infer the directory name
        name = archive_path
        for suffix in (".tar.gz", ".tgz", ".tar.bz2", ".zip", ".tar"):
            if name.endswith(suffix):
                name = name[: -len(suffix)]
                break
        dir_name = name.split("/")[-1]  # handle full paths

    # Build the absolute path of the extraction directory
    extraction_path = tmp_dir + "/" + dir_name

    # Choose extraction command based on archive type
    if archive_path.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path]
    elif archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
        cmd = ["tar", "xzf", archive_path]
    elif archive_path.endswith(".tar.bz2"):
        cmd = ["tar", "xjf", archive_path]
    elif archive_path.endswith(".tar"):
        cmd = ["tar", "xf", archive_path]
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    # Execute the extraction
    try:
        subprocess.run(
            cmd,
            cwd=tmp_dir,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Extraction failed for {archive_path}: {e.stderr.strip()}"
        ) from e

    # Return the file URL of the extracted repository
    return f"file://{extraction_path}"

