    if old_scale is None or old_scale == 0:
        raise ValueError("cannot rescale: graph scale unknown or zero")

    # Compute scaling factor
    try:
        scale_factor = float(other) / float(old_scale)
    except Exception as exc:
        raise ValueError(f"invalid scale value: {exc}") from exc

