        coord_data = getattr(self, last_coord)
        if isinstance(coord_data, (list, tuple)):
            new_coord = [v * scale_factor for v in coord_data]
        else:
            try:
                new_coord = coord_data * scale_factor
            except Exception:
                new_coord = None
        setattr(self, last_coord, new_coord)

        # Rescale associated error data if present
        err_attr = f"{last_coord}err"
        if hasattr(self, err_attr):
            err_data = getattr(self, err_attr)
            if isinstance(err_data, (list, tuple)):
