    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Helper to extract bin contents from a histogram
    def _get_bins_and_edges(h):
        # Try a few common patterns for histogram objects
        if hasattr(h, "bins") and callable(getattr(h, "bins")):
            return list(h.bins()), getattr(h, "edges", None)
        if hasattr(h, "contents"):
            return list(h.contents), getattr(h, "edges", None)
        if hasattr(h, "edges") and hasattr(h, "histo"):
            # e.g., a custom histogram wrapper
            return list(h.histo.contents), h.edges
        # Fallback: treat the histogram as an iterable of bin contents
        if not hasattr(h, "__iter__"):
            raise TypeError("Unsupported histogram type")
        # Assume edges can be inferred from length
        try:
            # Try to get histogram edges via a property
            edges = getattr(h, "edges", None)
            if edges is None:
                raise AttributeError
        except AttributeError:
            raise ValueError("Histogram must expose edges or have a supported structure")
        return list(h), edges

    # Sanity checks for get_coordinate
    valid_coords = {"left", "right", "middle"}
    if get_coordinate not in valid_coords:
        raise ValueError(f"get_coordinate must be one of {valid_coords}, got {get_coordinate!r}")

    # Default value function
    if make_value is None:
        make_value = lambda bin_: bin_

    try:
        bins, edges = _get_bins_and_edges(hist)
    except Exception as exc:
        raise ValueError(f"Cannot interpret histogram: {exc}") from exc

    if edges is None:
        raise ValueError("Histogram does not provide edges")
    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    # Compute X coordinates
    x_coords = []
    for i in range(len(bins)):
        left = edges[i]
        right = edges[i + 1]
        if get_coordinate == "left":
            x_coords.append(left)
        elif get_coordinate == "right":
            x_coords.append(right)
        else:  # "middle"
            x_coords.append(0.5 * (left + right))

