            n_y = len(first_val)
        else:
            n_y = 1
        if len(field_names) != 1 + n_y:
            raise ValueError(
                f"field_names length ({len(field_names)}) must match number of Y fields ({1 + n_y})"
            )
        for bin_ in bins:
            val = make_value(bin_)
            if n_y == 1:
                y_values.append([val])
            else:
                y_values.append(list(val))

