def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    try:
        import os
    except ImportError as exc:
        raise ImportError("The os module is required for path manipulation.") from exc

    if not root:
        raise ValueError("Root cannot be empty or None.")

    norm_root = os.path.normpath(root)
    norm_path = os.path.normpath(path)

    try:
        rel = os.path.relpath(norm_path, norm_root)
    except ValueError as exc:
        raise ValueError(f"Failed to strip root '{root}' from path '{path}': {exc}") from exc

    if rel == ".":
        # path is identical to root
        return ""

    if rel.startswith(".."):
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'.")

    return rel
